package com.smartseating.ui;

import com.smartseating.dao.RoomDAO;
import com.smartseating.model.*;
import com.smartseating.service.PrintService;
import com.smartseating.util.*;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;

public class RoomFrame extends AppFrame {
    private final RoomDAO dao=new RoomDAO();private final JTextField room=new JTextField(),building=new JTextField("Main Block"),floor=new JTextField("1"),rows=new JTextField("5"),columns=new JTextField("6"),capacity=new JTextField();private final JComboBox<String> status=new JComboBox<>(new String[]{"AVAILABLE","UNAVAILABLE"});private final JTable table=new JTable();private Room selected;
    public RoomFrame(User user){super("Room Management",user);UI.frame(this,1120,680);build();refresh();}
    private void build(){content.add(title("Room Management"),BorderLayout.NORTH);JPanel form=UI.formPanel();UI.addField(form,0,"Room Number",room);UI.addField(form,1,"Building",building);UI.addField(form,2,"Floor",floor);UI.addField(form,3,"Rows",rows);UI.addField(form,4,"Columns",columns);UI.addField(form,5,"Capacity (Rows × Columns)",capacity);UI.addField(form,6,"Status",status);rows.getDocument().addDocumentListener((SimpleDocumentListener)()->calc());columns.getDocument().addDocumentListener((SimpleDocumentListener)()->calc());JPanel a=new JPanel(new GridLayout(3,2,7,7));a.setOpaque(false);JButton add=button("ADD ROOM",UI.TEAL),update=button("UPDATE ROOM",UI.BLUE),del=button("DELETE ROOM",new Color(190,66,66)),clear=button("CLEAR",UI.MUTED),print=button("PRINT",UI.ORANGE),quick=button("QUICK ROOM SETUP",UI.ORANGE);for(JButton b:new JButton[]{add,update,del,clear,print,quick})a.add(b);GridBagConstraints g=new GridBagConstraints();g.gridx=0;g.gridy=7;g.gridwidth=2;g.fill=GridBagConstraints.HORIZONTAL;g.insets=new Insets(14,6,6,6);form.add(a,g);content.add(white(form),BorderLayout.WEST);UI.tableStyle(table);content.add(white(UI.scroll(table)),BorderLayout.CENTER);add.addActionListener(e->save());update.addActionListener(e->update());del.addActionListener(e->delete());clear.addActionListener(e->clear());print.addActionListener(e->PrintService.print("Room List",text()));quick.addActionListener(e->new QuickRoomSetupFrame(currentUser).setVisible(true));table.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&table.getSelectedRow()>=0)load();});if("TEACHER".equals(currentUser.getRole())){add.setEnabled(false);update.setEnabled(false);del.setEnabled(false);}}
    private void calc(){try{int r=Integer.parseInt(rows.getText().trim()),c=Integer.parseInt(columns.getText().trim());capacity.setText(String.valueOf(r*c));}catch(Exception ignored){capacity.setText("");}}
    private Room read(){int r=Validation.positive(rows.getText(),"Rows"),c=Validation.positive(columns.getText(),"Columns");return new Room(0,Validation.text(room.getText(),"Room number"),Validation.text(building.getText(),"Building"),Validation.positive(floor.getText(),"Floor"),r,c,r*c,(String)status.getSelectedItem());}private void save(){try{dao.save(read());clear();refresh();}catch(Exception ex){error(ex);}}private void update(){try{if(selected==null)throw new IllegalArgumentException("Select a room first.");Room x=read();x.setId(selected.getId());dao.update(x);clear();refresh();}catch(Exception ex){error(ex);}}private void delete(){try{if(selected==null)throw new IllegalArgumentException("Select a room first.");if(confirm("Delete selected room?")){dao.delete(selected.getId());clear();refresh();}}catch(Exception ex){error(ex);}}private void load(){int r=table.getSelectedRow();selected=new Room((int)table.getValueAt(r,0),String.valueOf(table.getValueAt(r,1)),String.valueOf(table.getValueAt(r,2)),Integer.parseInt(String.valueOf(table.getValueAt(r,3))),Integer.parseInt(String.valueOf(table.getValueAt(r,4))),Integer.parseInt(String.valueOf(table.getValueAt(r,5))),Integer.parseInt(String.valueOf(table.getValueAt(r,6))),String.valueOf(table.getValueAt(r,7)));room.setText(selected.getRoomNumber());building.setText(selected.getBuilding());floor.setText(String.valueOf(selected.getFloor()));rows.setText(String.valueOf(selected.getRows()));columns.setText(String.valueOf(selected.getColumns()));capacity.setText(String.valueOf(selected.getCapacity()));status.setSelectedItem(selected.getStatus());}private void clear(){selected=null;room.setText("");building.setText("Main Block");floor.setText("1");rows.setText("5");columns.setText("6");calc();table.clearSelection();}private void refresh(){try{DefaultTableModel m=new DefaultTableModel(new Object[]{"ID","Room","Building","Floor","Rows","Columns","Capacity","Status"},0);for(Room x:dao.findAll())m.addRow(new Object[]{x.getId(),x.getRoomNumber(),x.getBuilding(),x.getFloor(),x.getRows(),x.getColumns(),x.getCapacity(),x.getStatus()});table.setModel(m);UI.tableStyle(table);}catch(Exception ex){error(ex);}}private String text(){StringBuilder b=new StringBuilder("ROOM LIST\n\n");for(int i=0;i<table.getRowCount();i++)b.append(table.getValueAt(i,1)).append(" | ").append(table.getValueAt(i,2)).append(" | capacity ").append(table.getValueAt(i,6)).append(" | ").append(table.getValueAt(i,7)).append("\n");return b.toString();}
    private interface SimpleDocumentListener extends javax.swing.event.DocumentListener {void changed();default void insertUpdate(javax.swing.event.DocumentEvent e){changed();}default void removeUpdate(javax.swing.event.DocumentEvent e){changed();}default void changedUpdate(javax.swing.event.DocumentEvent e){changed();}}
}
